            }
            ptr++;
            h->uid = atoi(ptr);
            while (*ptr && !isspace(*ptr)) {
                ptr++;
            }
        } else if (!strncmp(ptr, "INTERNALDATE", 12)) {
            ptr += 12;
            if (*ptr != ' ' || *ptr != '"') {
                return -1; // Invalid format
            }
            ptr++;
            char *date_start = ptr;
            while (*ptr && *ptr != '"') {
                ptr++;
            }
            if (*ptr != '"') {
                return -1; // Unterminated quoted string
            }
            *ptr = '\0';
            strncpy(h->internal_date, date_start, sizeof(h->internal_date) - 1);
            ptr++;
        } else if (!strncmp(ptr, "RFC822.SIZE", 11)) {
            ptr += 11;
