}

int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *p = s;
    int in_field = 0;
    char field_name[128] = {0};
    char value[1024] = {0};

    while (*p) {
        if (isspace(*p)) {
            if (in_field) {
                if (strcasecmp(field_name, "FLAGS") == 0) {
                    char *v = p + 1;
                    while (*v && !isspace(*v)) {
                        v++;
                    }
                    size_t len = v - (p + 1);
                    h->flags = strndup(p + 1, len);
                } else if (strcasecmp(field_name, "UID") == 0) {
                    char *v = p + 1;
                    while (*v && !isspace(*v)) {
                        v++;
                    }
                    size_t len = v - (p + 1);
                    h->uid = atoi(strndup(p + 1, len));
                } else if (strcasecmp(field_name, "INTERNALDATE") == 0) {
                    char *v = p + 1;
                    while (*v && !isspace(*v)) {
                        v++;
                    }
                    size_t len = v - (p + 1);
                    h->internaldate = strndup(p + 1, len);
                } else if (strcasecmp(field_name, "RFC822.SIZE") == 0) {
                    char *v = p + 1;
                    while (*v && !isspace(*v)) {
                        v++;
                    }
                    size_t len = v - (p + 1);
                    h->size = atoi(strndup(p + 1, len));
                } else if (strcasecmp(field_name, "BODY") == 0 || strcasecmp(field_name, "RFC822.HEADER") == 0) {
                    return -2;
                } else {
                    // Unknown field
                    return -1;
                }
                in_field = 0;
                p = v - 1;
            }
        } else if (isalpha(*p)) {
            if (!in_field) {
                size_t i = 0;
                while (isalnum(*p) || *p == '.') {
                    field_name[i++] = *p++;
                    if (i >= sizeof(field_name) - 1) {
                        return -1;
                    }
                }
                field_name[i] = '\0';
                p--;
                in_field = 1;
            }
        }
        p++;
    }

    if (in_field) {
        return -1;
    }

    return 0;
