int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    char *p = s;

    while (*p) {
        // Skip whitespace
        while (*p && isspace((unsigned char)*p)) {
            p++;
        }

        if (!*p) {
            break;
        }

        // Check for known fields
        if (strncmp(p, "FLAGS", 5) == 0) {
            p += 5;
            // Skip to the opening parenthesis
            while (*p && *p != '(') {
                p++;
            }
            p++; // Skip '('
            h->flags = p;
            // Find the closing parenthesis
            while (*p && *p != ')') {
                p++;
            }
            *p = '\0'; // Null-terminate the flags string
            p++;
        } else if (strncmp(p, "UID", 3) == 0) {
            p += 3;
            while (*p && isspace((unsigned char)*p)) {
                p++;
            }
            if (!*p) {
                return -1;
            }
            h->uid = atoi(p);
            // Move to the end of the number
            while (*p && isdigit((unsigned char)*p)) {
                p++;
            }
        } else if (strncmp(p, "INTERNALDATE", 12) == 0) {
            p += 12;
            while (*p && isspace((unsigned char)*p)) {
                p++;
            }
            if (!*p) {
                return -1;
            }
            h->internal_date = p;
            // Skip quoted string
            if (*p == '"') {
                p++;
                while (*p && *p != '"') {
                    p++;
                }
                if (*p == '"') {
                    p++;
                }
            }
        } else if (strncmp(p, "RFC822.SIZE", 11) == 0) {
            p += 11;
            while (*p && isspace((unsigned char)*p)) {
                p++;
            }
            if (!*p) {
                return -1;
            }
            h->size = atoi(p);
            // Move to the end of the number
            while (*p && isdigit((unsigned char)*p)) {
                p++;
            }
        } else if (strncmp(p, "BODY", 4) == 0 || strncmp(p, "RFC822.HEADER", 13) == 0) {
            return -2;
        } else {
            return -1;
        }
    }

    return 0;
}

int parse_imap_fetch_response(struct ImapHeader *h, char *s) {
    if (!h || !s) {
        return -1;
    }

    char *ptr = s;
    char field[256];
    int field_index = 0;
    int in_value = 0;
    int in_quotes = 0;

    while (*ptr) {
        if (*ptr == ' ' && !in_value && !in_quotes) {
            // End of a field name
            field[field_index] = '\0';
            field_index = 0;

            if (strcmp(field, "FLAGS") == 0) {
                // Skip parsing of FLAGS for now
            } else if (strcmp(field, "UID") == 0) {
                // Parse UID value
                ptr++;
                h->uid = 0;
                while (*ptr && *ptr != ' ' && *ptr != ')' && !in_quotes) {
                    if (*ptr == '"') {
                        in_quotes = 1;
                        ptr++;
                        continue;
                    }
                    if (*ptr >= '0' && *ptr <= '9') {
                        h->uid = h->uid * 10 + (*ptr - '0');
                    }
                    ptr++;
                }
            } else if (strcmp(field, "INTERNALDATE") == 0) {
                // Parse INTERNALDATE value
                ptr++;
                if (*ptr == '"') {
                    in_quotes = 1;
                    ptr++;
                }
                h->internal_date[0] = '\0';
                while (*ptr && *ptr != '"' && *ptr != ' ' && *ptr != ')') {
                    strncat(h->internal_date, ptr, 1);
                    ptr++;
                }
                if (in_quotes && *ptr == '"') {
                    in_quotes = 0;
                    ptr++;
                }
            } else if (strcmp(field, "RFC822.SIZE") == 0) {
                // Parse RFC822.SIZE value
                ptr++;
                h->size = 0;
                while (*ptr && *ptr != ' ' && *ptr != ')' && !in_quotes) {
                    if (*ptr >= '0' && *ptr <= '9') {
                        h->size = h->size * 10 + (*ptr - '0');
                    }
                    ptr++;
                }
            } else if (strcmp(field, "BODY") == 0 || strcmp(field, "RFC822.HEADER") == 0) {
                return -2;
            } else {
                // Unknown field
                return -1;
            }
        } else if (!in_value) {
            // Collect field name
            field[field_index++] = *ptr;
            if (field_index >= sizeof(field) - 1) {
                // Field name too long
                return -1;
            }
        } else {
            // In a value, skip until end
            if (*ptr == '"' && in_quotes) {
                in_quotes = 0;
            } else if (*ptr == ')' && !in_quotes) {
                // End of value
                in_value = 0;
            }
        }
        ptr++;
    }

    return 0;
}
